    15  void
    16  pscopyheaders (FILE *from, FILE *to, Document d)
    17  {
    18      char *comment;
    19      Boolean pages_written = False;
    20      int here;
    21      FileData fd;
    22
    23      fd = ps_io_init(from);
    24
    25      here = d->beginheader;
    26      while ((comment=pscopyuntil(fd,to,here,d->endheader,"%%Pages:"))) {
    27         SMESSAGE(comment)
    28         here = ps_io_ftell(fd);
    29         if (pages_written) {
    30            PS_free(comment);
    31            continue;
    32         }
    33         fputs("%%Pages: (atend)\n", to);
    34         pages_written = True;
    35         PS_free(comment);
    36      }
    37
    38      if (!pages_written && !d->epsf)
    39          fputs("%%Pages: (atend)\n", to);
    40
    41      pscopyuntil(fd, to, d->beginpreview, d->endpreview,NULL);
    42      pscopyuntil(fd, to, d->begindefaults, d->enddefaults,NULL);
    43      pscopyuntil(fd, to, d->beginprolog, d->endprolog,NULL);
    44      pscopyuntil(fd, to, d->beginsetup, d->endsetup,NULL);
    45
    46      ps_io_exit(fd);
    47  }
