    50  pscopypage (FILE *from, FILE *to, Document d, unsigned int page, unsigned int n_page)
    51  {
    52      FileData fd;
    53      char *comment;
    54
    55      fd = ps_io_init(from);
    56
    57      comment = pscopyuntil(fd,to,d->pages[page].begin,d->pages[page].end, "%%Page:");
    58      fprintf(to, "%%%%Page: %s %d\n",d->pages[page].label, n_page);
    59      PS_free(comment);
    60      pscopyuntil(fd, to, -1, d->pages[page].end,NULL);
    61
    62      ps_io_exit(fd);
    63  }
