    65  void
    66  pscopytrailer (FILE *from, FILE *to, Document d, unsigned int n_pages)
    67  {
    68      FileData fd;
    69      Boolean pages_written = False;
    70      char *comment;
    71      int here;
    72
    73      fd = ps_io_init(from);
    74
    75      here = d->begintrailer;
    76      if (!d->epsf) {
    77          pscopyuntil(fd, to, here, here + strlen ("%%Trailer") + 1, NULL);
    78          here = ps_io_ftell(fd);
    79          fprintf(to, "%%%%Pages: %d\n",n_pages);
    80      }
    81
    82      while ((comment = pscopyuntil(fd, to, here, d->endtrailer, "%%Pages:"))) {
    83          here = ps_io_ftell(fd);
    84          if (pages_written) {
    85            PS_free(comment);
    86            continue;
    87          }
    88          pages_written = True;
    89          PS_free(comment);
    90      }
    91
    92      ps_io_exit(fd);
    93  }
