    95  /*##########################################################*/
    96  /* pscopydoc */
    97  /* Copy the headers, marked pages, and trailer to fp */
    98  /*##########################################################*/
    99
   100  void
   101  pscopydoc(dest_file,src_filename,d,pagelist)
   102      FILE *dest_file;
   103      char *src_filename;
   104      Document d;
   105      char *pagelist;
   106  {
   107      FILE *src_file;
   108      char text[PSLINELENGTH];
   109      char *comment;
   110      Boolean pages_written = False;
   111      Boolean pages_atend = False;
   112      int pages;
   113      int page = 1;
   114      unsigned int i, j;
   115      int here;
   116      FileData fd;
   117
   118      BEGINMESSAGE(pscopydoc)
   119
   120      INFSMESSAGE(copying from file, src_filename)
   121      src_file = fopen(src_filename, "rb");
   122      fd = ps_io_init(src_file);
   123
   124      i=0;
   125      pages=0;
   126      while (pagelist[i]) { if (pagelist[i]=='*') pages++; i++; }
   127      INFIMESSAGE(number of pages to be copied,pages)
   128
   129      here = d->beginheader;
   130      while ((comment=pscopyuntil(fd,dest_file,here,d->endheader,"%%Pages:"))) {
   131         SMESSAGE(comment)
   132         here = ps_io_ftell(fd);
   133         if (pages_written || pages_atend) {
   134            PS_free(comment);
   135            continue;
   136         }
   137         sscanf(comment+length("%%Pages:"), "%256s", text);
   138         if (strcmp(text, "(atend)") == 0) {
   139            fputs(comment, dest_file);
   140            pages_atend = True;
   141         } else {
   142            switch (sscanf(comment+length("%%Pages:"), "%*d %u", &i)) {
   143               case 1:
   144                  fprintf(dest_file, "%%%%Pages: %d %d\n", pages, i);
   145                  break;
   146               default:
   147                  fprintf(dest_file, "%%%%Pages: %d\n", pages);
   148                  break;
   149            }
   150            pages_written = True;
   151         }
   152         PS_free(comment);
   153     }
   154     pscopyuntil(fd, dest_file, d->beginpreview, d->endpreview,NULL);
   155     pscopyuntil(fd, dest_file, d->begindefaults, d->enddefaults,NULL);
   156     pscopyuntil(fd, dest_file, d->beginprolog, d->endprolog,NULL);
   157     pscopyuntil(fd, dest_file, d->beginsetup, d->endsetup,NULL);
   158
   159     for (i = 0; i < d->numpages; i++) {
   160        if (d->pageorder == DESCEND) j = (d->numpages - 1) - i;
   161        else                         j = i;
   162        if (pagelist[j]=='*') {
   163            comment = pscopyuntil(fd,dest_file,d->pages[i].begin,d->pages[i].end, "%%Page:");
   164            fprintf(dest_file, "%%%%Page: %s %d\n",d->pages[i].label, page++);
   165            PS_free(comment);
   166            pscopyuntil(fd, dest_file, -1, d->pages[i].end,NULL);
   167        }
   168     }
   169
   170     here = d->begintrailer;
   171     while ((comment = pscopyuntil(fd, dest_file, here, d->endtrailer, "%%Pages:"))) {
   172        here = ps_io_ftell(fd);
   173        if (pages_written) {
   174           PS_free(comment);
   175           continue;
   176        }
   177        switch (sscanf(comment+length("%%Pages:"), "%*d %u", &i)) {
   178           case 1:
   179              fprintf(dest_file, "%%%%Pages: %d %d\n", pages, i);
   180              break;
   181           default:
   182              fprintf(dest_file, "%%%%Pages: %d\n", pages);
   183              break;
   184        }
   185        pages_written = True;
   186        PS_free(comment);
   187     }
   188     fclose(src_file);
